CREATE TABLE food_standard (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL, category VARCHAR(60) NOT NULL, specification VARCHAR(255), safety_requirement TEXT, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier (id UUID PRIMARY KEY, name VARCHAR(160) NOT NULL, credit_code VARCHAR(30) UNIQUE NOT NULL, contact_name VARCHAR(60), contact_phone VARCHAR(30), qualification_status VARCHAR(30) NOT NULL, rating NUMERIC(3,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_plan (id UUID PRIMARY KEY, plan_no VARCHAR(40) UNIQUE NOT NULL, title VARCHAR(160) NOT NULL, organization VARCHAR(120) NOT NULL, budget NUMERIC(14,2) NOT NULL, status VARCHAR(30) NOT NULL, required_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inquiry (id UUID PRIMARY KEY, inquiry_no VARCHAR(40) UNIQUE NOT NULL, plan_id UUID REFERENCES procurement_plan(id), title VARCHAR(160) NOT NULL, deadline TIMESTAMPTZ, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE bid (id UUID PRIMARY KEY, inquiry_id UUID REFERENCES inquiry(id), supplier_id UUID REFERENCES supplier(id), amount NUMERIC(14,2) NOT NULL, remark VARCHAR(500), submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(inquiry_id, supplier_id));
CREATE TABLE purchase_order (id UUID PRIMARY KEY, order_no VARCHAR(40) UNIQUE NOT NULL, supplier_id UUID REFERENCES supplier(id), plan_id UUID REFERENCES procurement_plan(id), total_amount NUMERIC(14,2) NOT NULL, status VARCHAR(30) NOT NULL, expected_delivery DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delivery (id UUID PRIMARY KEY, delivery_no VARCHAR(40) UNIQUE NOT NULL, order_id UUID REFERENCES purchase_order(id), vehicle_no VARCHAR(30), delivered_at TIMESTAMPTZ, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inspection (id UUID PRIMARY KEY, delivery_id UUID REFERENCES delivery(id), inspector VARCHAR(80) NOT NULL, result VARCHAR(30) NOT NULL, temperature NUMERIC(5,2), note VARCHAR(500), inspected_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inventory_lot (id UUID PRIMARY KEY, lot_no VARCHAR(60) UNIQUE NOT NULL, standard_id UUID REFERENCES food_standard(id), supplier_id UUID REFERENCES supplier(id), quantity NUMERIC(12,2) NOT NULL, unit VARCHAR(20) NOT NULL, received_date DATE NOT NULL, expiry_date DATE, status VARCHAR(30) NOT NULL);
CREATE TABLE settlement (id UUID PRIMARY KEY, settlement_no VARCHAR(40) UNIQUE NOT NULL, order_id UUID REFERENCES purchase_order(id), amount NUMERIC(14,2) NOT NULL, status VARCHAR(30) NOT NULL, due_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_bid_inquiry ON bid(inquiry_id); CREATE INDEX idx_lot_standard ON inventory_lot(standard_id);
